import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { fetchUsersAsync, selectUsersState, updateUserAsync, deleteUserAsync } from "./userSlice";
import "./UserList.css";

function UserList() {
  const dispatch = useDispatch();
  const { users, loading, error } = useSelector(selectUsersState);

  const [editUserId, setEditUserId] = useState(null);
  const [editData, setEditData] = useState({});

  useEffect(() => {
    dispatch(fetchUsersAsync());
  }, [dispatch]);

  const handleEditClick = (user) => {
    // Deep copy user data to editData
    setEditUserId(user.id);
    setEditData({
      ...user,
      profile: { ...user.profile }  // important for nested profile
    });
  };

  const handleChange = (key, value, nested = null) => {
    if (nested) {
      setEditData({
        ...editData,
        [nested]: { ...editData[nested], [key]: value }
      });
    } else {
      setEditData({ ...editData, [key]: value });
    }
  };

  const handleSave = async () => {
    try {
      await dispatch(updateUserAsync(editData));
      setEditUserId(null);
    } catch (err) {
      console.error("Update failed:", err);
    }
  };

  const handleDelete = (id) => {
    if (window.confirm("Are you sure you want to delete this user?")) {
      dispatch(deleteUserAsync(id));
    }
  };

  if (loading) return <p>Loading users...</p>;
  if (error) return <p style={{ color: "red" }}>Error: {error}</p>;

  return (
    <div className="userlist-container">
      <h2>User Management</h2>
      <table className="user-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Username</th>
            <th>Email</th>
            <th>Status</th>
            <th>Bio</th>
            <th>Phone</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.length > 0 ? users.map(u => (
            <tr key={u.id}>
              <td>{u.id}</td>

              {/* Username */}
              <td>
                {editUserId === u.id ? (
                  <input
                    type="text"
                    value={editData.username}
                    onChange={e => handleChange("username", e.target.value)}
                  />
                ) : u.username}
              </td>

              {/* Email */}
              <td>
                {editUserId === u.id ? (
                  <input
                    type="text"
                    value={editData.email}
                    onChange={e => handleChange("email", e.target.value)}
                  />
                ) : u.email}
              </td>

              {/* Status */}
              <td>
                {editUserId === u.id ? (
                  <select
                    value={editData.is_active ? "Active" : "Inactive"}
                    onChange={e => handleChange("is_active", e.target.value === "Active")}
                  >
                    <option>Active</option>
                    <option>Inactive</option>
                  </select>
                ) : u.is_active ? "Active" : "Inactive"}
              </td>

              {/* Bio */}
              <td>
                {editUserId === u.id ? (
                  <input
                    type="text"
                    value={editData.profile.bio}
                    onChange={e => handleChange("bio", e.target.value, "profile")}
                  />
                ) : u.profile.bio}
              </td>

              {/* Phone */}
              <td>
                {editUserId === u.id ? (
                  <input
                    type="text"
                    value={editData.profile.phone}
                    onChange={e => handleChange("phone", e.target.value, "profile")}
                  />
                ) : u.profile.phone}
              </td>

              {/* Actions */}
              <td>
                {editUserId === u.id ? (
                  <>
                    <button className="save-btn" onClick={handleSave}>Save</button>
                    <button className="cancel-btn" onClick={() => setEditUserId(null)}>Cancel</button>
                  </>
                ) : (
                  <>
                    <button className="edit-btn" onClick={() => handleEditClick(u)}>Edit</button>
                    <button className="delete-btn" onClick={() => handleDelete(u.id)}>Delete</button>
                  </>
                )}
              </td>
            </tr>
          )) : (
            <tr>
              <td colSpan="7" style={{ textAlign: "center" }}>No users found</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

export default UserList;
